#[path="../media.rs"]mod media;
#[path="../mixer.rs"]mod mixer;
#[path="../export.rs"]mod export;
#[path="../catalog.rs"]mod catalog;
#[path="../save_folder.rs"]mod save_folder;
fn main(){use std::{path::Path,sync::{Arc,atomic::AtomicBool},time::Instant};let input=Path::new("Clips/wave-lanes-fixture.mp4");let hash=std::fs::read(input).unwrap();for mode in [export::Mode::Fast,export::Mode::Exact,export::Mode::Share720,export::Mode::Small480,export::Mode::Target10,export::Mode::Target20,export::Mode::TargetCustom(1)]{let(tx,_rx)=std::sync::mpsc::channel();let start=Instant::now();let p=export::export(Path::new("capture-engine.exe"),input,1.0,7.0,mode,Some(mixer::AudioMix::default()),Arc::new(AtomicBool::new(false)),tx).unwrap();let size=std::fs::metadata(&p).unwrap().len();assert!(media::has_separate_audio(&p),"Source tracks lost for {mode:?}: {}",p.display());assert_eq!(media::track_kinds(&p).unwrap().iter().filter(|k|*k==b"soun").count(),4);if let Some(cap)=export::target_bytes(mode){assert!(size<=cap);}println!("PASS mode={mode:?} duration={:.3} bytes={size} elapsed_ms={} path={}",media::duration(&p).unwrap(),start.elapsed().as_millis(),p.display());std::fs::remove_file(p).unwrap();}let(tx,_)=std::sync::mpsc::channel();assert!(export::export(Path::new("capture-engine.exe"),input,0.0,9.0,export::Mode::Exact,Some(mixer::AudioMix::default()),Arc::new(AtomicBool::new(true)),tx).is_err());assert_eq!(std::fs::read(input).unwrap(),hash);println!("PASS cancelled export preserves original bytes");}
